import { mkdirSync, mkdtempSync, realpathSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { previewSource } from './preview-source';

/*
 * A phone's preview is made only from a file inside the media folder, by its real path (Sessions 31–36,
 * SEC-10): a link in the media folder that leads out of it is refused. Generated bytes only.
 */

function folders() {
  const root = mkdtempSync(join(tmpdir(), 'drashti-preview-source-'));
  const mediaDir = join(root, 'Media');
  const outside = join(root, 'Elsewhere');
  mkdirSync(mediaDir);
  mkdirSync(outside);
  writeFileSync(join(mediaDir, 'inside.png'), Buffer.alloc(16, 1));
  writeFileSync(join(outside, 'secret.png'), Buffer.alloc(16, 2));
  // A folder in the media folder that is a link to one outside it.
  symlinkSync(outside, join(mediaDir, 'linked'), 'junction');
  return { mediaDir };
}

describe('the file a phone’s preview is made from (SEC-10)', () => {
  it('is a file inside the media folder, by its real path', () => {
    const { mediaDir } = folders();
    const source = previewSource('m1', {
      mediaDir,
      kindAndFile: () => ({ kind: 'image', path: 'inside.png', missing: false }),
      sharpened: () => null,
    });
    expect(source).toEqual({ path: realpathSync.native(join(mediaDir, 'inside.png')), kind: 'image' });
  });

  it('is refused through a link in the media folder that leads out of it, a picture or its sharpened copy', () => {
    const { mediaDir } = folders();
    expect(
      previewSource('m1', {
        mediaDir,
        kindAndFile: () => ({ kind: 'image', path: 'linked/secret.png', missing: false }),
        sharpened: () => null,
      }),
    ).toBeNull();
    expect(
      previewSource('m1_s50', {
        mediaDir,
        kindAndFile: () => null,
        sharpened: () => 'linked/secret.png',
      }),
    ).toBeNull();
  });
});
